const base="/api/v1/organizations/{orgId}/server-access" as const;
export default function BrowserTerminal(){const {org,failed}=useOrg();if(failed)return <ErrorText>Could not load your organization.</ErrorText>;if(!org)return <Loading/>;return <TerminalWorkspace key={org.id} orgId={org.id}/>;}
function checkFailure(reason:string){return reason==="ssh_authentication_failed"?"SSH authentication failed. Verify that the target SSH listener allows this account, trusts this organization's SSH CA, and has the exact account principal below.":reason==="ssh_host_key_mismatch"?"SSH host fingerprint changed. Verify the target host key independently before updating the pinned fingerprint.":reason}
