 const [search,setSearch]=useState("");const [serverPage,setServerPage]=useState(1);const [serverPageSize,setServerPageSize]=useState(20);const [accountPage,setAccountPage]=useState(1);const [accountPageSize,setAccountPageSize]=useState(20);
 const [detailStep,setDetailStep]=useState<"connection"|"accounts"|"access">("accounts");const [manualAccount,setManualAccount]=useState<{server:Server;account:string}>();
 const [editorRequest,setEditorRequest]=useState<{server:Server;account:string}>();
 const [params]=useSearchParams();const requestedView=params.get("view")??"servers";const [register,setRegister]=useState(false);const [selectedServer,setSelectedServer]=useState<string>();const [editServer,setEditServer]=useState<Server>();const [grantServer,setGrantServer]=useState<Server>();const [disableServer,setDisableServer]=useState<Server>();
 const [imported,setImported]=useState<ImportedRecording>();const [replay,setReplay]=useState<string>();const [confirmation,setConfirmation]=useState<{kind:"grant"|"session"|"server";id:string}>();
 const [data,setData]=useState<Workspace>();const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [reload,setReload]=useState(0);const [mfa,setMfa]=useState<string>();const mfaRetry=useRef<()=>Promise<void>>();const [{connections,selectedTab},setConnectionState]=useState<{connections:{session:Session;serverName:string;os:string;passwordRef:{current:string}}[];selectedTab?:string}>({connections:[]});const setSelectedTab=(id:string)=>setConnectionState(current=>({...current,selectedTab:id}));const [rdpRequest,setRdpRequest]=useState<{server:Server;account:string}>();const [rdpEntry,setRdpEntry]=useState("");const [trust,setTrust]=useState<components["schemas"]["ServerAccessTrust"]>();const [nodes,setNodes]=useState<Node[]>([]);const [members,setMembers]=useState<Member[]>([]);const [groups,setGroups]=useState<UserGroup[]>([]);
 recordingAuthority.current=data?.can_manage===true;
