 useEffect(()=>{if(!data?.can_manage&&!data?.can_grant)return;let live=true;void Promise.all([data.can_manage?api.GET("/api/v1/organizations/{orgId}/nodes",{params:{path}}):Promise.resolve({data:[]}),data.can_grant?api.GET("/api/v1/organizations/{orgId}/members",{params:{path}}):Promise.resolve({data:[]}),data.can_grant?api.GET("/api/v1/organizations/{orgId}/groups",{params:{path}}):Promise.resolve({data:[]})]).then(([n,m,g])=>{if(live){setNodes((n.data??[]).filter(n=>n.status==="active"&&n.enrolled_kind==="gateway"));setMembers((m.data??[]).filter(m=>m.status==="active"));setGroups(g.data??[])}}).catch(()=>{if(live)setError("Could not reach the server or grant directory.")});return()=>{live=false}},[orgId,data?.can_manage,data?.can_grant]);
 useEffect(()=>{if(data?.can_manage&&!data.sessions.some(s=>["pending","connecting","connected"].includes(s.status)))return;if(!data)return;const timer=setInterval(()=>setReload(v=>v+1),3000);return()=>clearInterval(timer)},[data?.sessions]);
 async function act<T>(fn:()=>Promise<{data?:T;error?:unknown}>,success?:(d:T)=>void,location?:string){if(busy)return;setBusy(true);setError("");try{const r=await fn();if(r.error||!r.data){if(apiErrorCode(r.error)==="mfa_required"){mfaRetry.current=()=>act(fn,success,location);setMfa(location??"workspace");return}setError(apiErrorMessage(r.error,"The request could not be completed."));return}success?.(r.data);setReload(v=>v+1)}catch{setError("Could not reach the control plane.")}finally{setBusy(false)}}
 async function saveRecordingPolicy(policy:Pick<Workspace,"mfa_freshness_seconds"|"recording_retention_days"|"recording_max_session_bytes"|"recording_max_org_bytes">){if(!workspaceLive.current||!recordingAuthority.current||busy||recordingPolicyLocked.current)return;recordingPolicyLocked.current=true;try{await act(async()=>{const latest=await api.GET(base,{params:{path}});if(!workspaceLive.current||!recordingAuthority.current)return {error:{message:"The workspace changed. Reload before saving."}};if(latest.error||!latest.data)return {error:latest.error??{message:"Could not read the current Server Access setting."}};if(latest.data.can_manage!==true||typeof latest.data.enabled!=="boolean")return {error:{message:"The current Server Access setting is unavailable for editing."}};return api.PUT(base,{params:{path},body:{enabled:latest.data.enabled,...policy}})})}finally{recordingPolicyLocked.current=false}}
 async function connect(s:Server,account:string,check=false,password?:string){if(!check&&s.os==="windows"&&!password){if(window.location.protocol!=="https:"){setError("Open the control plane over HTTPS for Windows RDP.");return};setRdpRequest({server:s,account});return};await act(()=>check?api.POST("/api/v1/organizations/{orgId}/server-access/servers/{serverId}/check",{params:{path:{...path,serverId:s.id}},body:{server_id:s.id,account}}):api.POST("/api/v1/organizations/{orgId}/server-access/sessions",{params:{path},body:{server_id:s.id,account}}),v=>{if(!check){setConnectionState(current=>({connections:[...current.connections,{session:v,serverName:s.name,os:s.os??"linux",passwordRef:{current:password??""}}],selectedTab:v.id}));setRdpRequest(undefined);setRdpEntry("")}},`account:${s.id}:${account}`)}
 function closeConnection(id:string){setConnectionState(current=>{const index=current.connections.findIndex(c=>c.session.id===id);const remaining=current.connections.filter(c=>c.session.id!==id);return {connections:remaining,selectedTab:current.selectedTab===id?remaining[Math.min(index,remaining.length-1)]?.session.id:current.selectedTab}});setReload(v=>v+1)}
