  <AppAccessPagination page={currentServerPage} pageSize={serverPageSize} count={serverRows.slice((currentServerPage-1)*serverPageSize,currentServerPage*serverPageSize).length} hasNext={currentServerPage*serverPageSize<serverRows.length} busy={busy} onPageChange={setServerPage} onPageSizeChange={size=>{setServerPageSize(appAccessPageSize(String(size)));setServerPage(1)}} previousLabel="Previous servers" nextLabel="Next servers"/>
